public class ServerShipmentService : IShipmentService
{
    private static readonly List<ShipmentDetail> _shipments = GenerateSeedData();

    public Task<List<ShipmentSummary>> GetAllShipmentsAsync()
    {
        var summaries = _shipments.Select(s => new ShipmentSummary
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Destination = s.Destination,
            Status = s.Status,
            EstimatedDelivery = s.EstimatedDelivery,
            RecipientName = s.RecipientName
        }).ToList();

        return Task.FromResult(summaries);
    }

    public Task<ShipmentDetail?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(
            s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
